package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.NotPositiveException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_divide_TriageGen0Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testDivide_NullArgument() {
        Complex c = new Complex(1.0, 1.0);
        try {
            c.divide(null);
            fail("Expected NullArgumentException");
        } catch (NullArgumentException e) {
            // Success
        }
    }

    @Test
    public void testDivide_NaN_Result() {
        Complex nan = Complex.NaN;
        Complex divisor = new Complex(1.0, 1.0);
        Complex result = nan.divide(divisor);
        assertTrue(result.isNaN());

        Complex normal = new Complex(1.0, 1.0);
        Complex nanDivisor = Complex.NaN;
        Complex result2 = normal.divide(nanDivisor);
        assertTrue(result2.isNaN());
    }

    @Test
    public void testDivide_ZeroDivisor_ReturnsNaN() {
        // isZero (dividend) is true, divisor is zero
        Complex zero = Complex.ZERO;
        Complex result = zero.divide(Complex.ZERO);
        assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_ZeroDivisor_ReturnsINF() {
        // isZero (dividend) is false, divisor is zero
        Complex normal = new Complex(1.0, 1.0);
        Complex result = normal.divide(Complex.ZERO);
        assertTrue(result.isInfinite());
    }

    @Test
    public void testDivide_InfiniteDivisor_FiniteDividend_ReturnsZERO() {
        Complex normal = new Complex(1.0, 1.0);
        Complex inf = Complex.INF;
        Complex result = normal.divide(inf);
        assertEquals(0.0, result.getReal(), EPSILON);
        assertEquals(0.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testDivide_BothInfinite_ReturnsNonZero() {
        // If both are infinite, it bypasses the "divisor.isInfinite() && !isInfinite()" check
        Complex inf = Complex.INF;
        Complex result = inf.divide(inf);
        // Result of INF/INF is NaN in standard math, let's verify logic flow
        assertTrue(result.isNaN() || result.isInfinite() || (result.getReal() != 0));
    }

    @Test
    public void testDivide_Branch_AbsC_LessThan_AbsD() {
        // c = 1.0, d = 2.0 -> |1| < |2| is true
        Complex dividend = new Complex(4.0, 2.0);
        Complex divisor = new Complex(1.0, 2.0);
        // (4+2i) / (1+2i) = [(4+2i)(1-2i)] / [1^2 + 2^2] 
        // = [4 - 8i + 2i - 4i^2] / 5 = [8 - 6i] / 5 = 1.6 - 1.2i
        Complex result = dividend.divide(divisor);
        assertEquals(1.6, result.getReal(), EPSILON);
        assertEquals(-1.2, result.getImaginary(), EPSILON);
    }

    @Test
    public void testDivide_Branch_AbsC_GreaterThan_AbsD() {
        // c = 2.0, d = 1.0 -> |2| < |1| is false
        Complex dividend = new Complex(4.0, 2.0);
        Complex divisor = new Complex(2.0, 1.0);
        // (4+2i) / (2+1i) = [(4+2i)(2-1i)] / [2^2 + 1^2]
        // = [8 - 4i + 4i - 2i^2] / 5 = [10] / 5 = 2.0 + 0.0i
        Complex result = dividend.divide(divisor);
        assertEquals(2.0, result.getReal(), EPSILON);
        assertEquals(0.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testDivide_Branch_AbsC_Equals_AbsD() {
        // c = 1.0, d = 1.0 -> |1| < |1| is false, goes to else block
        Complex dividend = new Complex(2.0, 2.0);
        Complex divisor = new Complex(1.0, 1.0);
        // (2+2i) / (1+1i) = 2.0
        Complex result = dividend.divide(divisor);
        assertEquals(2.0, result.getReal(), EPSILON);
        assertEquals(0.0, result.getImaginary(), EPSILON);
    }
}
